md_view_default_set_st_states_ent_sensor:
{% set st = states('[[ent:sensor:operating_state]]') %}
{% set power = states('[[ent:switch:power_switch]]') %}
{% set heat_h = is_state('[[ent:binary_sensor:heating_heater]]', 'on') %}
{% set hw_h = is_state('[[ent:binary_sensor:hotwater_heater]]', 'on') %}
{% set defrost = is_state('[[ent:binary_sensor:defrost_active]]', 'on') %}
{% if power == 'off' %}
⚪ **Тепловий насос ВИМКНЕНО** (очікування). Увімкніть головний вимикач нижче, щоб відновити опалення або ГВП.
{% elif st == 'alarm' or is_state('[[ent:binary_sensor:alarm_stop]]', 'on') %}
🔴 **Зупинка через аварію.** Відкрийте вкладку **Діагностика**, усуньте причину та натисніть Скинути.
{% elif defrost or st == 'defrost' %}
❄️ **Розморожування (Defrost).** На 3–5 хвилин насос реверсує цикл, щоб розтопити лід на зовнішньому блоці. Коротке зниження температури води є нормою.
{% elif st == 'antilegionella' %}
🛡️ **Дезінфекція (Антилегіонела).** Нагрівання бойлера ГВП до високої температури.
{% elif st == 'heating' %}
🔥 **Опалення будинку.** Подача теплої води в контур опалення.
{% elif st == 'hot_water' %}
🚿 **Нагрів гарячої води (ГВП).** Заряджання бойлера.
{% elif st == 'heating_hot_water' %}
🔥🚿 **Одночасне опалення та нагрів ГВП.**
{% elif st == 'cooling' or st == 'cooling_hot_water' %}
🧊 **Охолодження.** Охолодження води для контуру кондиціювання.
{% elif st == 'idle' %}
🟢 **Очікування — цільова температура досягнута.** Пауза, доки вода не охолоне на заданий гістерезис.
{% elif is_state('[[ent:binary_sensor:compressor_running]]', 'on') %}
🔥 **Компресор працює** (увімкніть *Розрахункові сенсори* в налаштуваннях інтеграції для детального опису).
{% else %}
🟢 **Тепловий насос УВІМКНЕНО (очікування).**
{% endif %}
{% if heat_h or hw_h %}
⚠️ **Увага:** Працює допоміжний електротен (нагрів 1:1 — підвищене споживання електроенергії).
{% endif %}

md_view_diagnostics_set_errors_ent_binar:
{% set errors = [
  '[[ent:binary_sensor:error_hotwater_sensor]]',
  '[[ent:binary_sensor:error_ambient_sensor]]',
  '[[ent:binary_sensor:error_coil_sensor]]',
  '[[ent:binary_sensor:error_outlet_sensor]]',
  '[[ent:binary_sensor:error_high_pressure_sensor]]',
  '[[ent:binary_sensor:error_phase_sequence]]',
  '[[ent:binary_sensor:error_water_flow]]',
  '[[ent:binary_sensor:error_high_temp_heating]]',
  '[[ent:binary_sensor:error_outlet_gas_temp]]',
  '[[ent:binary_sensor:error_inlet_sensor]]',
  '[[ent:binary_sensor:error_exhaust_high]]',
  '[[ent:binary_sensor:error_low_temp_cooling]]',
  '[[ent:binary_sensor:error_inlet_gas_sensor]]',
  '[[ent:binary_sensor:error_low_pressure]]',
  '[[ent:binary_sensor:error_high_pressure]]',
  '[[ent:binary_sensor:error_coil_temp_high]]',
  '[[ent:binary_sensor:error_high_pressure_sensor2]]',
  '[[ent:binary_sensor:error_low_pressure_sensor]]',
  '[[ent:binary_sensor:error_antifreeze_secondary]]',
  '[[ent:binary_sensor:error_antifreeze_primary]]',
  '[[ent:binary_sensor:error_ambient_temp_low]]',
  '[[ent:binary_sensor:error_inverter_module]]',
  '[[ent:binary_sensor:error_dc_fan2]]',
  '[[ent:binary_sensor:error_dc_fan1]]'
] %}
{% set active = namespace(items=[]) %}
{% for e in errors %}
  {% if is_state(e, 'on') %}
    {% set active.items = active.items + [state_attr(e, 'friendly_name') or e] %}
  {% endif %}
{% endfor %}
{% if is_state('[[ent:binary_sensor:alarm_stop]]', 'on') or active.items | length > 0 %}
🔴 **ВИЯВЛЕНО АВАРІЮ! Активні помилки ({{ active.items | length }}):**
{% for item in active.items %}
- ⚠️ {{ item }}
{% endfor %}
**Що перевірити перед скиданням:**
- *Помилка протоку води:* прочистьте сітчастий фільтр, стравіть повітря, перевірте закриті крани.
- *Високий тиск:* перевірте циркуляцію води та чистоту теплообмінника.
- *Низький тиск / Захист від замерзання:* перевірте обмерзання зовнішнього блоку та кількість фреону.
{% else %}
🟢 **Активних аварій немає (0 / 24 помилок).** Усі датчики та захисти в нормі.
{% endif %}

md_view_optimization_set_cycle_states_en:
{% set cycle = states('[[ent:sensor:compressor_last_run_duration]]') %}
{% set prev_cycle = state_attr('[[ent:sensor:compressor_last_run_duration]]', 'last_completed_minutes') %}
{% set comp_on = is_state('[[ent:binary_sensor:compressor_running]]', 'on') %}
{% set def_dur = states('[[ent:sensor:defrost_last_duration]]') %}
{% set def_int = states('[[ent:sensor:defrost_last_interval]]') %}
{% set coil_d = states('[[ent:sensor:coil_ambient_delta]]') %}
{% set water_d = states('[[ent:sensor:water_delta_t]]') %}
{% set eco_d = states('[[ent:sensor:eco_setpoint_delta]]') %}
{% set op = states('[[ent:sensor:operating_state]]') %}
{% set defrost = is_state('[[ent:binary_sensor:defrost_active]]', 'on') or op == 'defrost' %}
{% set heating_run = op in ['heating', 'hot_water', 'heating_hot_water'] %}
{% set hz = states('[[ent:sensor:compressor_frequency]]') | float(0) %}
{% set heat_h = is_state('[[ent:binary_sensor:heating_heater]]', 'on') %}
{% set hw_h = is_state('[[ent:binary_sensor:hotwater_heater]]', 'on') %}
{% set ch_h = is_state('[[ent:binary_sensor:chassis_heater]]', 'on') %}
**Швидка оцінка за поточними показниками:**
{% if comp_on %}
{% if is_number(prev_cycle) and prev_cycle | float > 0 %}
{% if prev_cycle | float < 15 %}
- 🟡 **Короткий попередній цикл компресора ({{ prev_cycle }} хв; поточний триває: {{ cycle }} хв):** Якщо це не завершення ГВП, насос може тактувати. Збільште *Гістерезис опалення (P03)* на 1°C або *G03*.
{% else %}
- 🟢 **Попередній цикл компресора ({{ prev_cycle }} хв; поточний триває: {{ cycle }} хв):** Довга стабільна робота з мінімальними пусковими втратами.
{% endif %}
{% elif is_number(cycle) %}
- 🔄 **Триває перший цикл компресора ({{ cycle }} хв):** Оцінка тактування з'явиться після завершення першого повного циклу.
{% endif %}
{% elif is_number(prev_cycle) and prev_cycle | float > 0 %}
{% if prev_cycle | float < 15 %}
- 🟡 **Короткий цикл компресора ({{ prev_cycle }} хв):** Якщо це не завершення ГВП, насос може тактувати. Збільште *Гістерезис опалення (P03)* на 1°C або *G03*.
{% else %}
- 🟢 **Тривалість циклу компресора ({{ prev_cycle }} хв):** Довга стабільна робота.
{% endif %}
{% elif is_number(cycle) and cycle | float > 0 %}
{% if cycle | float < 15 %}
- 🟡 **Короткий цикл компресора ({{ cycle }} хв):** Якщо це не завершення ГВП, насос може тактувати. Збільште *Гістерезис опалення (P03)* на 1°C або *G03*.
{% else %}
- 🟢 **Тривалість циклу компресора ({{ cycle }} хв):** Довга стабільна робота.
{% endif %}
{% endif %}
{% if defrost %}
- ❄️ **Триває розморожування:** Насос реверсував цикл і тимчасово забирає тепло з води (`Delta T води` від'ємна — це норма). Перевірка протоку відновиться після розморожування.
{% elif is_number(water_d) and hz > 0 and heating_run %}
{% if water_d | float < 0 %}
- 🔄 **Стабілізація після розморожування / пуску (Delta T {{ water_d }} °C):** Охолоджена вода ще проходить через теплообмінник.
{% elif water_d | float < 2.0 %}
- 🟡 **Мала Delta T води ({{ water_d }} °C):** Циркуляційний насос качає занадто швидко або тепло погано відбирається. Перевірте *G04 (Цільова Delta T)* і швидкість DC-насоса.
{% elif water_d | float > 7.5 %}
- 🟡 **Велика Delta T води ({{ water_d }} °C):** Слабкий протік — прочистьте фільтр або збільште протік для кращого COP.
{% else %}
- 🟢 **Delta T води ({{ water_d }} °C):** Збалансований теплообмін.
{% endif %}
{% endif %}
{% if heat_h or hw_h %}
- 🔴 **Електротен УВІМКНЕНО (COP = 1.0)!** Знизьте пороги *G05/G07* (напр., до -12°C) і збільште затримку *G06/G08* до 45–60 хв.
{% else %}
- 🟢 **Електротени вимкнені:** Усе тепло виробляє економічний компресор.
{% endif %}
{% if ch_h %}
- ℹ️ **Підігрів піддону активний:** Споживає ~43 Вт для захисту зливу від замерзання.
{% endif %}
{% if is_number(eco_d) %}
- 📊 **Подача vs крива ECO:** відхилення **{{ eco_d }} °C** (кожен 1°C нижче на подачі економить ~2–3 % електроенергії).
{% endif %}
{% if is_number(coil_d) %}
- ❄️ **Обмерзання (Зовні - Ламелі):** **{{ coil_d }} °C** (0 °C = чисті ламелі / розморожування; ріст до 8–10 °C свідчить про наростання інею).
{% endif %}
{% if is_number(def_dur) and def_dur | float > 0 %}
- ⏱️ **Останнє розморожування:** тривало **{{ def_dur }} хв**{% if is_number(def_int) and def_int | float > 0 %}, інтервал від попереднього: **{{ def_int }} хв**{% endif %}. Нормальна тривалість — 3–5 хв.
{% endif %}

carel_status_summary:
{% set power = states('[[ent:switch:power]]') %}
{% set st = states('[[ent:sensor:unit_status]]') %}
{% set run_mode = states('[[ent:sensor:unit_run_mode]]') %}
{% set alarm = is_state('[[ent:binary_sensor:alarm_active]]', 'on') %}
{% set alarms = states('[[ent:sensor:active_alarms]]') %}
{% set heater = is_state('[[ent:binary_sensor:electric_heater]]', 'on') %}
{% if alarm %}
🔴 **Активна аварія:** {{ alarms }}. Перевірте вкладку **Діагностика** перед скиданням.
{% elif power == 'off' %}
⚪ **Тепловий насос ВИМКНЕНО** ({{ st }}).
{% elif is_state('[[ent:binary_sensor:compressor_running]]', 'on') %}
🔥 **Компресор працює** — Статус: **{{ st }}**, Режим: **{{ run_mode }}**.
{% else %}
🟢 **Очікування** — Статус: **{{ st }}**.
{% endif %}
{% if heater %}
⚠️ **Увага:** Активний додатковий електронагрівач.
{% endif %}
